<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {groupRequest,request} from '../api'
import MathText from './MathText.vue'
import LearningPanel from './LearningPanel.vue'
function templateId(){if(globalThis.crypto?.randomUUID)return crypto.randomUUID();return Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')}
const props=defineProps({group:Object,user:Object,compact:Boolean,catalog:Array,initialTask:String})
const emit=defineEmits(['stage','plan','help','continue','opened'])
const conflictedDraft=ref(null)
const jobs=ref([]),aiConsent=ref(false),bindingHandle=ref(''),planVersions=ref([])
function ojResult(job){try{const r=JSON.parse(job.RESULT);return r.status==='VERIFIED'?`已验证当日 AC · 账号 ${r.handle} · 提交编号 ${r.evidence_id}`:r.status==='NO_MATCH'?'未找到当日 AC；不代表知识检查失败':job.RESULT}catch{return job.RESULT}}
const taskJobs=computed(()=>jobs.value.filter(j=>j.TASK_ID===selected.value))
async function loadJobs(){try{const result=await request('identity','/study-jobs?group_id='+encodeURIComponent(props.group.id));if(active)jobs.value=result}catch(e){if(active)error.value=e.message}}
async function startJob(kind,reference_id){await request('identity','/study-jobs','POST',{group_id:props.group.id,task_id:selected.value,reference_id,kind,consent:aiConsent.value});await loadJobs();notice.value='检查已开始，可以离开页面后回来查看结果'}
async function jobAppeal(job){const reason=window.prompt('说明你对 AI 反馈的异议；同时可向组长提出检查点申诉');if(reason){await request('identity','/study-jobs/'+job.ID+'/appeal','POST',{reason});await loadJobs()}}
const api=groupRequest(props.group),base='/group/study'
const data=ref(null),error=ref(''),notice=ref(''),busy=ref(false),selected=ref(null),detail=ref(null),legacy=ref(false)
const body=ref(''),minutes=ref(45),evidence=ref(''),checkpoint=ref(''),variant=ref(''),reason=ref(''),adjustValue=ref(''),adjustKind=ref('DEFER')
const reviewHistory=ref({})
const planEditor=ref(false),planId=ref(''),plan=ref({title:'',stage:'',deadline:'',change_note:'首次发布',expected_version:0,tasks:[{id:templateId(),title:'',problem_key:'',criterion:''}]})
const copyTarget=ref('')
const studyMinutes=ref(45),pending=ref(null),weekly=ref(null),retro=ref({body:'',next_plan:'',confirmed:false}),reviewText=ref(''),reviewDay=ref(''),help=ref({title:'',body:''})
const labels={NOT_STARTED:'未开始',IN_PROGRESS:'进行中',SUBMITTED:'已提交',NEEDS_WORK:'待补充',COMPLETED:'已完成',DEFERRED:'已延期',SKIP_PENDING:'跳过待审批',SKIPPED:'已跳过',PENDING:'待检查',PASSED:'检查通过',APPEALED:'申诉处理中',OUTDATED:'已被后续调整替代',UNAVAILABLE:'检查暂不可用',PROCESSING:'处理中'}
const label=s=>labels[s]||s
const todo=computed(()=>data.value?.tasks.filter(t=>!['COMPLETED','SKIPPED'].includes(t.STATUS))||[])
const needs=computed(()=>data.value?.tasks.filter(t=>t.STATUS==='NEEDS_WORK')||[])
const reviews=computed(()=>data.value?.reviews.filter(r=>r.DUE_DAY<=data.value.today)||[])
const unavailable=computed(()=>{const latest=new Map();for(const j of jobs.value){const key=j.KIND+':'+j.REFERENCE_ID;if(!latest.has(key))latest.set(key,j)}return [...latest.values()].filter(j=>j.STATUS==='UNAVAILABLE')})
const completed=computed(()=>data.value?.tasks.filter(t=>t.STATUS==='COMPLETED').length||0)
const cacheKey=computed(()=>`study-draft:v2:${props.user.id}:${props.group.id}:${selected.value||''}`)
let active=true,initializing=false,dirty=false,timer,poll,saveQueue=Promise.resolve()
function cache(){if(initializing||!selected.value||!dirty)return;sessionStorage.setItem(cacheKey.value,JSON.stringify({body:body.value,minutes:minutes.value,evidence:evidence.value,revision:detail.value?.task.REVISION}))}
watch([body,minutes,evidence],()=>{if(initializing)return;dirty=true;cache();clearTimeout(timer);timer=setTimeout(()=>saveDraft().catch(e=>{error.value=e.message}),900)},{flush:'sync'})
async function load(){const result=await api(base+'/overview');if(!active)return;data.value=result;bindingHandle.value=result.binding?.[0]?.HANDLE||'';emit('stage',result.plans[0]?.STAGE||'尚未加入阶段计划');if(result.is_leader)pending.value=await api(base+'/pending')}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();if(active)await load()}catch(e){if(active)error.value=e.message}finally{if(active)busy.value=false}}
async function openTask(task){await saveDraft();conflictedDraft.value=null;const result=await api(base+'/tasks/'+task.ID);if(!active)return;initializing=true;selected.value=task.ID;detail.value=result;body.value=result.task.DRAFT;minutes.value=result.task.MINUTES||45;checkpoint.value='';evidence.value=result.task.DRAFT_EVIDENCE||'';dirty=false;const cached=sessionStorage.getItem(cacheKey.value);if(cached){try{const d=JSON.parse(cached);if(d.revision===result.task.REVISION){body.value=d.body;minutes.value=d.minutes;evidence.value=d.evidence||'';dirty=true;notice.value='已恢复当前群组的未同步草稿'}else {conflictedDraft.value=d;notice.value='检测到较新服务器草稿，未覆盖服务器；你仍可查看并恢复本窗口未同步的内容'}}catch{}}initializing=false}
function saveDraft(){clearTimeout(timer);cache();const write=async()=>{if(!dirty||!detail.value||!selected.value||['COMPLETED','SKIPPED'].includes(detail.value.task.STATUS))return;const task=selected.value,content=body.value,duration=minutes.value,proof=evidence.value,key=cacheKey.value;const saved=await api(base+'/tasks/'+task+'/draft','PUT',{body:content,minutes:Number(duration),evidence_note:proof,revision:detail.value.task.REVISION});if(selected.value===task){detail.value.task=saved;if(body.value===content&&minutes.value===duration&&evidence.value===proof){dirty=false;sessionStorage.removeItem(key)}else cache()}};saveQueue=saveQueue.catch(()=>{}).then(write);return saveQueue}
async function submit(){await saveDraft();await api(base+'/tasks/'+selected.value+'/submit','POST',{body:body.value,minutes:Number(minutes.value),evidence_note:evidence.value,revision:detail.value.task.REVISION});await openTask({ID:selected.value});notice.value='已正式提交。总结、OJ 通过与检查点分别记录，不代表已掌握。'}
async function adjust(){await saveDraft();await api(base+'/tasks/'+selected.value+'/adjust','POST',{kind:adjustKind.value,reason:reason.value,value:adjustValue.value});await openTask({ID:selected.value})}
function showReview(r){document.getElementById('review-'+r.ID)?.scrollIntoView({behavior:'smooth',block:'center'})}
async function copyPlan(p){if(!copyTarget.value)throw Error('请选择要复制到的群组');await request('identity','/study-overview/copy-plan','POST',{source_group:props.group.id,target_group:copyTarget.value,plan_id:p.PLAN_ID});notice.value='计划已复制，两个群组的计划与执行状态独立管理'}
function parseTasks(p){try{return JSON.parse(p.TASKS_JSON)}catch{return []}}
function addTemplate(){plan.value.tasks.push({id:templateId(),title:'',problem_key:'',criterion:''})}
function editPlan(p){planId.value=p?.PLAN_ID||'';plan.value=p?{title:p.TITLE,stage:p.STAGE,deadline:p.DEADLINE,change_note:'',expected_version:p.VERSION,tasks:parseTasks(p)}:{title:'',stage:'',deadline:'',change_note:'首次发布',expected_version:0,tasks:[{id:templateId(),title:'',problem_key:'',criterion:''}]};planEditor.value=true}
async function publish(){await api(base+'/plans'+(planId.value?'/'+planId.value+'/versions':''),'POST',plan.value);planEditor.value=false;notice.value='新版本已发布，成员现有任务及已完成记录保持原样'}
async function enroll(p){await api(base+'/plans/'+p.PLAN_ID+'/join','POST',{version:p.VERSION,minutes:studyMinutes.value});notice.value='已确认计划版本与个人学习时间，下面可领取任务'}
async function claim(p,t){const result=await api(base+'/plans/'+p.PLAN_ID+'/claim','POST',{version:p.VERSION,template_id:t.id});await load();await openTask({ID:result.id})}
async function sendCheckpoint(){const submission=detail.value.submissions[0];if(!submission)throw Error('请先正式提交学习总结');await api(base+'/tasks/'+selected.value+'/checkpoint','POST',{submission_id:submission.ID,answer:checkpoint.value,variant:variant.value});await openTask({ID:selected.value});notice.value='检查已提交，稍后可回来查看结果'}
async function assess(a){const feedback=window.prompt('填写检查反馈（不会自动声称知识掌握）');if(!feedback)return;const passed=window.confirm('本次检查是否通过？确定为通过，取消为待补充。');await api(base+'/checkpoints/'+a.ID+'/assess','POST',{passed,feedback})}
async function appeal(a){const text=window.prompt('说明申诉理由');if(text)await api(base+'/checkpoints/'+a.ID+'/appeal','POST',{reason:text})}
async function review(r){await api(base+'/reviews/'+r.ID+'/complete','POST',{reflection:reviewText.value,next_day:reviewDay.value});reviewText.value=''}
async function askHelp(){const r=await api(base+'/tasks/'+selected.value+'/help','POST',help.value);help.value={title:'',body:''};notice.value='求助已关联任务并发布到本群组交流区';await openTask({ID:selected.value});emit('help',r.discussion_id)}
async function resolve(h){const understanding=window.prompt('回填你现在对问题的理解');if(understanding){await api(base+'/help/'+h.ID+'/resolve','POST',{understanding});await openTask({ID:selected.value})}}
onMounted(()=>{run(async()=>{await load();await loadJobs();if(props.initialTask){await openTask({ID:props.initialTask});emit('opened')}});poll=setInterval(()=>{if(active&&!busy.value)loadJobs()},4000)})
onBeforeUnmount(()=>{clearInterval(poll);cache();clearTimeout(timer);saveDraft().catch(()=>{});active=false})
defineExpose({saveDraft})
</script>
<template>
 <section class="study-workflow" aria-label="群组学习工作台">
  <div class="section-head"><div><small class="eyebrow">YOUR NEXT STEP</small><h2>{{compact?'今日学习概览':'学习工作台'}}</h2></div><button class="secondary" :disabled="busy" @click="run(load)">刷新进度</button></div>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="study-notice" role="status">{{notice}}</p>
  <p v-if="!data&&!error">正在读取本群组的学习记录…</p>
  <template v-if="data">
   <p class="muted">{{group.name}} · {{data.today}} · 你的个人执行、复习和检查记录仅本人及必要的组长检查流程可见。</p>
   <article v-if="!detail" class="study-next card"><div><span class="eyebrow">01 / 今日待办</span><h3>{{todo[0]?.TITLE||'从一个阶段计划开始'}}</h3><p>{{todo.length?`${label(todo[0].STATUS)} · 截止 ${todo[0].DEADLINE}`:'先加入组长发布的计划，再领取适合自己的任务。'}}</p><p v-if="todo[0]" class="note">建议先推进此项：它是当前截止时间最早的未完成任务。</p></div><button v-if="todo.length" :disabled="busy" @click="compact?emit('continue',todo[0].ID):run(()=>openTask(todo[0]))">继续学习 →</button></article>
   <section v-if="!detail" class="study-attention"><h3>02 / 需要处理</h3><p v-if="!needs.length&&!reviews.length&&!unavailable.length" class="muted">暂无待补充检查点或到期复习。</p><button v-for="t in needs" :key="t.ID" class="secondary" :disabled="busy" @click="compact?emit('continue',t.ID):run(()=>openTask(t))">待补充 · {{t.TITLE}}</button><p v-if="reviews.length">{{reviews.length}} 项内容已到复习时间，建议先复习最近的薄弱点。</p><button v-for="r in reviews" :key="r.ID" class="secondary" @click="compact?emit('continue',''):showReview(r)">到期复习 · {{data.tasks.find(t=>t.ID===r.TASK_ID)?.TITLE}}</button><button v-for="j in unavailable" :key="j.ID" class="secondary" :disabled="busy" @click="compact?emit('continue',j.TASK_ID):run(()=>openTask({ID:j.TASK_ID}))">检查暂不可用 · {{j.KIND}} · 查看并重试</button></section>
   <section v-if="!detail" class="card"><span class="eyebrow">03 / 当前阶段进度</span><h3>{{data.plans[0]?.STAGE||'尚无阶段计划'}}</h3><progress :value="completed" :max="Math.max(data.tasks.length,1)"></progress><p>已完成 {{completed}} / {{data.tasks.length}} 项任务 · 阶段截止 {{data.plans[0]?.DEADLINE||'未设置'}}</p><p>检查点：待检查 {{data.attempts.filter(a=>a.STATUS==='PENDING').length}} · 待补充 {{data.attempts.filter(a=>a.STATUS==='NEEDS_WORK').length}} · 历次通过 {{data.attempts.filter(a=>a.STATUS==='PASSED').length}}</p><p class="note">完成任务、提交总结、OJ 通过、检查点通过是不同证据，系统不会自动认定知识已掌握。</p></section>
   <section v-if="compact&&data.announcements?.length"><h3>组内公告</h3><article v-for="n in data.announcements" :key="n.ID" class="card"><h4>{{n.TITLE}}</h4><MathText :text="n.BODY"/></article></section><template v-if="!compact">
    <div v-if="!detail" class="study-tasks"><button v-for="t in data.tasks" :key="t.ID" :class="['study-task',{selected:selected===t.ID}]" :disabled="busy" @click="run(()=>openTask(t))"><strong>{{t.TITLE}}</strong><span>{{label(t.STATUS)}} · {{t.PROBLEM_KEY}}</span><small>截止 {{t.DEADLINE}} · 领取版本 v{{t.PLAN_VERSION}}</small></button></div>
    <button v-if="detail" type="button" class="secondary" :disabled="busy" @click="run(async()=>{await saveDraft();detail=null;selected=null})">← 返回学习总览</button><div v-if="detail" class="study-detail">
     <section class="card"><div class="section-head"><h3>{{detail.task.TITLE}}</h3><span class="badge">{{label(detail.task.STATUS)}}</span></div><p>{{detail.task.PROBLEM_KEY}}</p><MathText :text="detail.task.CRITERION"/>
      <p v-if="conflictedDraft" class="study-notice">本窗口还有未同步内容：<button type="button" class="secondary" @click="body=conflictedDraft.body;minutes=conflictedDraft.minutes;evidence=conflictedDraft.evidence||'';conflictedDraft=null">恢复本窗口草稿供核对</button></p><form @submit.prevent="run(submit)"><label>学习过程与总结<textarea v-model="body" maxlength="12000" rows="8" :disabled="['COMPLETED','SKIPPED'].includes(detail.task.STATUS)" placeholder="记录思路、边界与仍不理解的地方；切换群组前自动保存草稿" required></textarea></label><div class="section-head"><label>学习分钟<input v-model.number="minutes" type="number" min="1" max="1440" required></label><span class="muted">{{dirty?'草稿待同步':'草稿已同步'}} · 版本 {{detail.task.REVISION}}</span></div><label>验证证据说明<textarea v-model="evidence" maxlength="2000" placeholder="可补充题目链接、提交编号；填写说明不等于 OJ 已验证"></textarea></label><div class="study-actions"><button type="button" class="secondary" :disabled="busy" @click="run(saveDraft)">保存草稿</button><button :disabled="busy||['SUBMITTED','COMPLETED','SKIPPED'].includes(detail.task.STATUS)">{{busy?'处理中…':'正式提交'}}</button></div></form>
      <h4>提交记录</h4><article v-for="s in detail.submissions" :key="s.ID" class="study-record"><small>{{s.CREATED_AT}} · {{s.PROBLEM_KEY}} · OJ：{{({NOT_CHECKED:'尚未验证',VERIFIED:'已验证当日 AC',NO_MATCH:'未找到当日 AC'})[s.OJ_STATUS]||'待验证'}}</small><MathText :text="s.BODY"/><p>{{s.EVIDENCE_NOTE}}</p><button type="button" class="secondary" :disabled="busy||jobs.some(j=>j.REFERENCE_ID===s.ID&&['PENDING','PROCESSING'].includes(j.STATUS))" @click="run(()=>startJob('OJ',s.ID))">同步 Codeforces 验证</button></article>
      <details><summary>从当前任务向同伴求助</summary><form @submit.prevent="run(askHelp)"><label>问题标题<input v-model="help.title" required maxlength="100"></label><label>公开给本组的内容<textarea v-model="help.body" required maxlength="12000"></textarea></label><p class="note">仅发布你在此处填写的内容，不会自动公开私人草稿和检查答案。</p><button :disabled="busy">发布组内求助</button></form></details><article v-for="h in detail.help" :key="h.ID"><p>求助状态：{{h.STATUS==='OPEN'?'待解决':'已解决'}} · {{h.RESOLUTION}}</p><button v-if="h.STATUS==='OPEN'" class="secondary" @click="run(()=>resolve(h))">解决并回填理解</button></article>
      <details><summary>调整历史</summary><p v-for="e in detail.events" :key="e.ID">{{e.KIND}} · {{e.REASON}} · {{e.DETAIL}}</p></details>
     </section>
     <section class="study-support">
      <article class="card"><h3>当前状态与截止时间</h3><p>{{label(detail.task.STATUS)}} · {{detail.task.DEADLINE}}</p><form @submit.prevent="run(adjust)"><label>调整方式<select v-model="adjustKind"><option value="DEFER">延期</option><option value="REPLACE">换题</option><option value="SKIP_REQUEST">申请跳过</option><option value="RESUME">继续学习</option></select></label><label v-if="adjustKind==='DEFER'||adjustKind==='REPLACE'">{{adjustKind==='DEFER'?'新的截止日期':'替换题目'}}<input v-model="adjustValue" :type="adjustKind==='DEFER'?'date':'text'" required maxlength="80"></label><label>调整原因<textarea v-model="reason" required maxlength="2000"></textarea></label><button :disabled="busy">记录调整</button></form></article>
      <article class="card"><h3>检查点与验证证据</h3><label class="consent"><input v-model="aiConsent" type="checkbox">允许将本任务正式提交、检查标准和回答发送给我的模型配置</label><form @submit.prevent="run(sendCheckpoint)"><label>理解回答 / 补充回答<textarea v-model="checkpoint" maxlength="12000" required></textarea></label><label>变式题说明<textarea v-model="variant" maxlength="2000"></textarea></label><button :disabled="busy||!detail.submissions.length">提交检查 / 复测</button></form><article v-for="a in detail.attempts" :key="a.ID" class="study-record"><strong>{{label(a.STATUS)}}</strong><MathText :text="a.ANSWER"/><p>{{a.FEEDBACK||'等待组长检查，可稍后回来查看'}}</p><button type="button" class="secondary" :disabled="busy||!aiConsent||jobs.some(j=>j.REFERENCE_ID===a.ID&&['PENDING','PROCESSING'].includes(j.STATUS))" @click="run(()=>startJob('AI',a.ID))">AI 辅助检查</button><button v-if="['PASSED','NEEDS_WORK'].includes(a.STATUS)" class="secondary" :disabled="busy" @click="run(()=>appeal(a))">对评价提出申诉</button></article></article>
      <article v-for="j in taskJobs" :key="j.ID" class="card"><strong>{{j.KIND==='AI'?'AI 辅助检查':'OJ 验证'}} · {{({SUCCEEDED:'检查已返回',PENDING:'排队中',PROCESSING:'处理中',UNAVAILABLE:'检查暂不可用'})[j.STATUS]}}</strong><MathText :text="j.KIND==='OJ'?ojResult(j):j.RESULT"/><p v-if="j.APPEAL">已记录异议：{{j.APPEAL}}</p><button v-if="j.STATUS==='UNAVAILABLE'" :disabled="busy||(j.KIND==='AI'&&!aiConsent)" @click="run(()=>startJob(j.KIND,j.REFERENCE_ID))">重试检查</button><button v-if="j.KIND==='AI'&&j.STATUS==='SUCCEEDED'" class="secondary" :disabled="busy" @click="run(()=>jobAppeal(j))">对 AI 评价提出异议</button></article><article class="card"><h3>关联资料</h3><p class="note">以下资料来自当前群组，可对照任务检查标准自行选用。</p><details v-for="r in detail.resources||[]" :key="r.ID"><summary>{{r.TITLE}}</summary><MathText :text="r.BODY"/></details></article><details class="card"><summary>Agent 辅助</summary><p>当前检索范围：本群组</p><button @click="emit('plan')">打开学习顾问</button></details>
     </section>
    </div>
    <template v-if="!detail"><form class="card" @submit.prevent="run(()=>api('/group/learning/oj-binding','PUT',{provider:'Codeforces',handle:bindingHandle}))"><h3>当前群组 Codeforces 绑定</h3><label>Codeforces 用户名<input v-model="bindingHandle" required pattern="[a-zA-Z0-9_.-]{3,24}"></label><p class="note">仅读取公开提交记录；用户名关联尚不能证明账号所有权。</p><button :disabled="busy">保存本组绑定</button></form><section><div class="section-head"><h3>阶段计划</h3><button v-if="data.is_leader" @click="editPlan()">发布阶段计划</button></div><label>我的每日学习时间（分钟）<input v-model.number="studyMinutes" type="number" min="1" max="1440"></label><article v-for="p in data.plans" :key="p.PLAN_ID" class="card"><div class="section-head"><h3>{{p.TITLE}} · v{{p.VERSION}}</h3><button v-if="data.is_leader" class="secondary" @click="editPlan(p)">发布新版本</button></div><p>{{p.STAGE}} · 截止 {{p.DEADLINE}}</p><p v-if="data.enrollments.find(e=>e.PLAN_ID===p.PLAN_ID)" class="badge">已加入 v{{data.enrollments.find(e=>e.PLAN_ID===p.PLAN_ID).VERSION}} · 每日 {{data.enrollments.find(e=>e.PLAN_ID===p.PLAN_ID).MINUTES}} 分钟</p><p class="study-notice">本版变更：{{p.CHANGE_NOTE}}</p><p class="note">更新计划后，已领取任务保持原版本，历史提交不变。</p><div class="study-actions"><button :disabled="busy" @click="run(()=>enroll(p))">确认加入此版本</button><button class="secondary" :disabled="busy" @click="run(async()=>planVersions=await api(base+'/plans/'+p.PLAN_ID+'/versions'))">查看版本历史</button><label>复制计划到<select v-model="copyTarget"><option value="">选择另一个群组</option><option v-for="g in (catalog||[]).filter(g=>g.id!==group.id)" :key="g.id" :value="g.id">{{g.name}}</option></select></label><button class="secondary" :disabled="busy||!copyTarget" @click="run(()=>copyPlan(p))">复制到其他群组</button><p class="note">需目标群组组长权限；仅复制计划内容，不复制学习进度。</p></div><div v-for="t in parseTasks(p)" :key="t.id" class="study-template"><div><strong>{{t.title}}</strong><p>{{t.problem_key}} · {{t.criterion}}</p></div><button class="secondary" :disabled="busy" @click="run(()=>claim(p,t))">领取 / 查看</button></div></article></section>
    <details v-if="planVersions.length" open><summary>计划版本历史</summary><article v-for="v in planVersions" :key="v.PLAN_ID+v.VERSION" class="card"><strong>{{v.TITLE}} · v{{v.VERSION}}</strong><p>{{v.CHANGE_NOTE}}</p><p v-for="t in parseTasks(v)" :key="t.id">{{t.title}} · {{t.problem_key}} · {{t.criterion}}</p></article></details><form v-if="planEditor" class="card" @submit.prevent="run(publish)"><h3>{{planId?'发布计划新版本':'发布阶段计划'}}</h3><label>计划名称<input v-model="plan.title" required maxlength="120"></label><label>当前阶段<input v-model="plan.stage" required maxlength="120"></label><label>阶段截止<input v-model="plan.deadline" type="date" required></label><label>版本变更说明<textarea v-model="plan.change_note" required maxlength="2000"></textarea></label><fieldset v-for="(t,i) in plan.tasks" :key="t.id"><legend>任务 {{i+1}}</legend><label>标题<input v-model="t.title" required maxlength="120"></label><label>题号 / 题目链接<input v-model="t.problem_key" required maxlength="80"></label><label>检查标准<textarea v-model="t.criterion" required maxlength="2000"></textarea></label><button v-if="plan.tasks.length>1" type="button" class="secondary" @click="plan.tasks.splice(i,1)">移除</button></fieldset><div class="study-actions"><button type="button" class="secondary" @click="addTemplate">添加任务</button><button :disabled="busy">发布不可变版本</button><button type="button" class="secondary" @click="planEditor=false">取消</button></div></form>
    <section><h3>个人复习队列</h3><p v-if="!data.reviews.length" class="muted">检查未通过的任务会进入私人复习队列。</p><article v-for="r in data.reviews" :key="r.ID" :id="'review-'+r.ID" class="card"><p>{{r.REASON}} · 下次复习 {{r.DUE_DAY}}</p><form @submit.prevent="run(()=>review(r))"><label>本次复习理解<textarea v-model="reviewText" required maxlength="4000"></textarea></label><label>下次复习日期<input v-model="reviewDay" type="date" required></label><button :disabled="busy">记录复习</button></form><label class="consent"><input type="checkbox" :checked="r.SHARED" :disabled="busy" @change="run(()=>api(base+'/reviews/'+r.ID+'/sharing','PUT',{shared:$event.target.checked}))">主动分享错题原因给本组成员</label><button class="secondary" :disabled="busy" @click="run(async()=>reviewHistory[r.ID]=await api(base+'/reviews/'+r.ID+'/history'))">查看历次复习</button><article v-for="h in reviewHistory[r.ID]||[]" :key="h.ID"><small>{{h.CREATED_AT}} · 下次 {{h.NEXT_DAY}}</small><MathText :text="h.REFLECTION"/></article></article></section>
    <section v-if="data.is_leader&&pending" class="card"><h3>组长待处理</h3><article v-for="a in pending.checkpoints" :key="a.ID"><strong>{{a.TITLE}} · {{label(a.STATUS)}}</strong><p>{{a.CRITERION}}</p><MathText :text="a.ANSWER"/><p v-if="a.APPEAL">申诉：{{a.APPEAL}}</p><button :disabled="busy" @click="run(()=>assess(a))">检查并反馈</button></article><article v-for="t in pending.skips" :key="t.ID"><strong>{{t.TITLE}} · 申请跳过</strong><button :disabled="busy" @click="run(async()=>{const reason=window.prompt('填写审批说明');if(reason)await api(base+'/tasks/'+t.ID+'/skip-decision','POST',{approved:window.confirm('确定批准跳过？取消为拒绝。'),reason})})">处理跳过申请</button></article></section></template>
   </template>
   <section v-if="!detail"><h3>04 / 学习记录与阶段复盘</h3><button class="secondary" :disabled="busy" @click="run(async()=>weekly=await api(base+'/weekly'))">查看本周卡点与完成情况</button><p v-if="weekly">按时完成 {{weekly.on_time}} · 延期完成 {{weekly.late}} · 本周到期未完成 {{weekly.unfinished}}<br>最近七天调整记录 {{weekly.blockers.length}} 条（完成情况按最近七天统计）</p><p v-for="e in weekly?.blockers||[]" :key="e.ID">{{e.CREATED_AT.slice(0,10)}} · {{e.KIND}} · {{e.REASON}} · {{e.DETAIL}}</p><form v-if="!compact" class="card" @submit.prevent="run(()=>api(base+'/retrospectives','POST',retro))"><label>本周复盘与卡点<textarea v-model="retro.body" required maxlength="4000"></textarea></label><label>下一阶段调整计划<textarea v-model="retro.next_plan" required maxlength="4000"></textarea></label><label class="consent"><input v-model="retro.confirmed" type="checkbox">确认下一阶段安排</label><button :disabled="busy">保存复盘</button></form><article v-for="r in data.retrospectives" :key="r.ID" class="card"><MathText :text="r.BODY"/><p>下一阶段：{{r.NEXT_PLAN}} · {{r.CONFIRMED?'已确认':'草案'}}</p></article></section>
   <details v-if="!compact&&!detail"><summary @click="legacy=true">第一版学习点、Codeforces 绑定与历史打卡</summary><LearningPanel v-if="legacy" :group="group" @plan="emit('plan')"/></details>
  </template>
 </section>
</template>
<style scoped>
.study-workflow{max-width:1200px;margin:auto}.study-next{display:flex;align-items:center;justify-content:space-between;gap:24px;background:linear-gradient(125deg,#edf3ff,#f8fbff);border-color:#dbe5fb}.study-next h3{font-size:24px;margin:12px 0}.study-attention{padding:16px 0 24px}.study-attention button{margin:4px}.study-notice{background:#eef6f1;border-left:3px solid #5d9479;padding:12px 16px;color:#244e3a}.study-tasks{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:24px 0}.study-task{display:flex;flex-direction:column;align-items:flex-start;gap:9px;background:white;color:#31415e;border:1px solid #e1e7f1;text-align:left;padding:18px}.study-task.selected{border-color:#526ceb;background:#f1f4ff}.study-detail{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,1fr);gap:20px;align-items:start}.study-support .card{padding:20px;margin-bottom:16px}.study-record{border-top:1px solid #e5eaf3;margin-top:18px;padding-top:14px;overflow-wrap:anywhere}.study-actions{display:flex;gap:8px;flex-wrap:wrap}.study-template{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #e8ecf4;padding:16px 0}progress{width:100%;height:10px;accent-color:#536fe8}details{margin:18px 0}summary{cursor:pointer;font-weight:600}fieldset{border:1px solid #e2e8f1;border-radius:10px;margin:18px 0;padding:16px}@media(max-width:1000px){.study-detail{grid-template-columns:1fr}}@media(max-width:600px){.study-next{display:block}.study-next button{margin-top:10px}}
